package com.gittexplorer.documentextractor.exception;
import com.gittexplorer.documentextractor.dto.ErrorResponse;import jakarta.servlet.http.HttpServletRequest;import java.time.Instant;import java.util.List;import java.util.UUID;import org.slf4j.Logger;import org.slf4j.LoggerFactory;import org.springframework.http.HttpStatus;import org.springframework.http.ResponseEntity;import org.springframework.web.HttpMediaTypeNotSupportedException;import org.springframework.web.bind.MissingServletRequestParameterException;import org.springframework.web.bind.annotation.ExceptionHandler;import org.springframework.web.bind.annotation.RestControllerAdvice;import org.springframework.web.multipart.MaxUploadSizeExceededException;import org.springframework.web.multipart.MultipartException;
@RestControllerAdvice public class GlobalExceptionHandler { private static final Logger log=LoggerFactory.getLogger(GlobalExceptionHandler.class); @ExceptionHandler({InvalidUploadException.class, MissingServletRequestParameterException.class, MultipartException.class}) public ResponseEntity<ErrorResponse> badRequest(Exception ex,HttpServletRequest req){return error(req,HttpStatus.BAD_REQUEST,ex.getMessage(),List.of());} @ExceptionHandler(UnsupportedDocumentTypeException.class) public ResponseEntity<ErrorResponse> unsupported(UnsupportedDocumentTypeException ex,HttpServletRequest req){return error(req,HttpStatus.UNSUPPORTED_MEDIA_TYPE,ex.getMessage(),List.of());} @ExceptionHandler(MaxUploadSizeExceededException.class) public ResponseEntity<ErrorResponse> tooLarge(MaxUploadSizeExceededException ex,HttpServletRequest req){return error(req,HttpStatus.PAYLOAD_TOO_LARGE,"Upload exceeds configured multipart limits",List.of());} @ExceptionHandler(HttpMediaTypeNotSupportedException.class) public ResponseEntity<ErrorResponse> media(HttpMediaTypeNotSupportedException ex,HttpServletRequest req){return error(req,HttpStatus.UNSUPPORTED_MEDIA_TYPE,ex.getMessage(),List.of());} @ExceptionHandler(InvalidRegexConfigurationException.class) public ResponseEntity<ErrorResponse> regex(InvalidRegexConfigurationException ex,HttpServletRequest req){return error(req,HttpStatus.INTERNAL_SERVER_ERROR,"Invalid regex configuration",List.of(ex.getMessage()));} @ExceptionHandler(Exception.class) public ResponseEntity<ErrorResponse> internal(Exception ex,HttpServletRequest req){log.error("Unhandled exception",ex);return error(req,HttpStatus.INTERNAL_SERVER_ERROR,"Internal server error",List.of());} private ResponseEntity<ErrorResponse> error(HttpServletRequest req,HttpStatus status,String message,List<String> details){String requestId=req.getHeader("X-Request-Id");if(requestId==null||requestId.isBlank())requestId=UUID.randomUUID().toString();return ResponseEntity.status(status).body(new ErrorResponse(requestId,Instant.now(),status.value(),status.getReasonPhrase(),message,details));} }
